// -------------------------------------------------------------------------
// 2) Informacion de cada voivodato: nombre en polaco, capital regional,
//    poblacion aproximada (fuente: estimaciones GUS ~2022/2023,
//    redondeadas) y color. La clave usada es "kod" (codigo ISO 3166-2
//    de cada voivodato polaco, ej. "PL-14"), que viene en el GeoJSON
//    de cada feature.
// -------------------------------------------------------------------------
const WOJEWODZTWO_INFO = {
  'PL-02': { nombre: 'Dolnoslaskie',          capital: 'Wroclaw',                    poblacion: 2884000, color: '#e6194b' },
  'PL-04': { nombre: 'Kujawsko-Pomorskie',    capital: 'Bydgoszcz (y Torun)',         poblacion: 2043000, color: '#3cb44b' },
  'PL-06': { nombre: 'Lubelskie',             capital: 'Lublin',                     poblacion: 2038000, color: '#4363d8' },
  'PL-08': { nombre: 'Lubuskie',              capital: 'Gorzow Wielkopolski (y Zielona Gora)', poblacion: 967000,  color: '#f58231' },
  'PL-10': { nombre: 'Lodzkie',               capital: 'Lodz',                       poblacion: 2323000, color: '#911eb4' },
  'PL-12': { nombre: 'Malopolskie',           capital: 'Cracovia',                   poblacion: 3413000, color: '#42d4f4' },
  'PL-14': { nombre: 'Mazowieckie',           capital: 'Varsovia',                   poblacion: 5423000, color: '#f032e6' },
  'PL-16': { nombre: 'Opolskie',              capital: 'Opole',                      poblacion: 933000,  color: '#bfef45' },
  'PL-18': { nombre: 'Podkarpackie',          capital: 'Rzeszow',                    poblacion: 2116000, color: '#469990' },
  'PL-20': { nombre: 'Podlaskie',             capital: 'Bialystok',                  poblacion: 1131000, color: '#9a6324' },
  'PL-22': { nombre: 'Pomorskie',             capital: 'Gdansk',                     poblacion: 2346000, color: '#800000' },
  'PL-24': { nombre: 'Slaskie',               capital: 'Katowice',                   poblacion: 4327000, color: '#808000' },
  'PL-26': { nombre: 'Swietokrzyskie',        capital: 'Kielce',                     poblacion: 1173000, color: '#e6beff' },
  'PL-28': { nombre: 'Warminsko-Mazurskie',   capital: 'Olsztyn',                    poblacion: 1360000, color: '#fabed4' },
  'PL-30': { nombre: 'Wielkopolskie',         capital: 'Poznan',                     poblacion: 3496000, color: '#dcbeff' },
  'PL-32': { nombre: 'Zachodniopomorskie',    capital: 'Szczecin',                   poblacion: 1667000, color: '#a9a9a9' },
};

// -------------------------------------------------------------------------
// 3) Ciudades principales que se muestran siempre con su nombre en el mapa
//    (las 16 capitales de voivodato; Varsovia ademas es la capital del pais).
// -------------------------------------------------------------------------
const CIUDADES_PRINCIPALES = [
  { nombre: 'Varsovia',            lon: 21.0122, lat: 52.2297, capital: true },
  { nombre: 'Cracovia',            lon: 19.9450, lat: 50.0647 },
  { nombre: 'Wroclaw (Breslavia)', lon: 17.0385, lat: 51.1079 },
  { nombre: 'Gdansk',              lon: 18.6466, lat: 54.3520 },
  { nombre: 'Poznan',              lon: 16.9252, lat: 52.4064 },
  { nombre: 'Lodz',                lon: 19.4560, lat: 51.7592 },
  { nombre: 'Szczecin',            lon: 14.5528, lat: 53.4285 },
  { nombre: 'Katowice',            lon: 19.0238, lat: 50.2649 },
  { nombre: 'Lublin',              lon: 22.5684, lat: 51.2465 },
  { nombre: 'Bialystok',           lon: 23.1688, lat: 53.1325 },
  { nombre: 'Kielce',              lon: 20.6286, lat: 50.8661 },
  { nombre: 'Olsztyn',             lon: 20.4801, lat: 53.7784 },
  { nombre: 'Rzeszow',             lon: 22.0047, lat: 50.0412 },
  { nombre: 'Opole',               lon: 17.9230, lat: 50.6751 },
  { nombre: 'Bydgoszcz',           lon: 18.0084, lat: 53.1235 },
  { nombre: 'Zielona Gora',        lon: 15.5058, lat: 51.9356 },
];

// -------------------------------------------------------------------------
// 4) Ajustes generales de la camara / vista inicial del mapa 3D.
// -------------------------------------------------------------------------
const CONFIG_CAMARA = {
  center: [19.4, 52.0], // aprox. centro geografico de Polonia
  zoom: 5.6,
  pitch: 58,   // inclinacion para que se note el relieve
  bearing: -8,
  maxPitch: 82,
};

// -------------------------------------------------------------------------
// 5) Estilo base del mapa (vectorial, gratuito, sin API key) + fuente del
//    terreno (elevacion) tambien gratuita y sin key.
// -------------------------------------------------------------------------
const ESTILO_BASE_URL = 'https://tiles.openfreemap.org/styles/liberty';
const TERRAIN_TILES_URL = 'https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png';

// =========================================================================
// A partir de aca arranca la logica del mapa.
// =========================================================================

const map = new maplibregl.Map({
  container: 'map',
  style: ESTILO_BASE_URL,
  ...CONFIG_CAMARA,
  antialias: true,
});

// Controles de navegacion (zoom +/-, brujula/inclinacion) arriba a la derecha.
map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), 'top-right');
map.addControl(new maplibregl.FullscreenControl(), 'top-right');
map.addControl(new maplibregl.ScaleControl({ unit: 'metric' }), 'bottom-right');

// Guarda cual es el voivodato actualmente seleccionado (para poder
// "desmarcarlo" cuando el usuario clickea otro).
let idVoivodatoSeleccionado = null;
// Guarda cual es el voivodato sobre el que esta el mouse (hover).
let idVoivodatoHover = null;

map.on('load', () => {
  ocultarPantallaCarga();

  // --- Terreno 3D -------------------------------------------------------
  map.addSource('terreno', {
    type: 'raster-dem',
    tiles: [TERRAIN_TILES_URL],
    tileSize: 256,
    encoding: 'terrarium',
    maxzoom: 15,
    attribution: 'Terreno: AWS Terrain Tiles (terrarium)',
  });
  map.setTerrain({ source: 'terreno', exaggeration: 1.4 });

  // Cielo con degrade, para reforzar la sensacion de "3D" al inclinar la camara.
  map.setSky({
    'sky-color': '#1b2a4a',
    'sky-horizon-blend': 0.6,
    'horizon-color': '#bcd9f0',
    'horizon-fog-blend': 0.5,
    'fog-color': '#d7e7f5',
    'fog-ground-blend': 0.6,
  });

  // --- Voivodatos (poligonos) --------------------------------------------
  map.addSource('voivodatos', {
    type: 'geojson',
    data: POLONIA_VOIVODATOS_GEOJSON,
    generateId: true, // necesario para poder usar feature-state (hover/seleccion)
  });

  // Relleno de cada voivodato con su color propio (definido en WOJEWODZTWO_INFO).
  map.addLayer({
    id: 'voivodatos-relleno',
    type: 'fill',
    source: 'voivodatos',
    paint: {
      'fill-color': construirExpresionDeColor(),
      'fill-opacity': [
        'case',
        ['boolean', ['feature-state', 'seleccionada'], false], 0.85,
        ['boolean', ['feature-state', 'hover'], false], 0.75,
        0.45,
      ],
    },
  });

  // Bordes de los voivodatos, mas gruesos si esta seleccionado.
  map.addLayer({
    id: 'voivodatos-borde',
    type: 'line',
    source: 'voivodatos',
    paint: {
      'line-color': [
        'case',
        ['boolean', ['feature-state', 'seleccionada'], false], '#ffffff',
        '#2b2b2b',
      ],
      'line-width': [
        'case',
        ['boolean', ['feature-state', 'seleccionada'], false], 3.5,
        1.2,
      ],
    },
  });

  agregarMarcadoresDeCiudades();
  configurarInteracciones();
});

// Si algo falla al cargar el estilo/tiles, igual sacamos la pantalla de carga
// para no dejar al usuario mirando un spinner infinito.
map.on('error', () => ocultarPantallaCarga());

/**
 * Arma la expresion de MapLibre ('match') que asigna a cada voivodato
 * el color definido en WOJEWODZTWO_INFO segun su codigo "kod".
 */
function construirExpresionDeColor() {
  const expresion = ['match', ['get', 'kod']];
  Object.entries(WOJEWODZTWO_INFO).forEach(([codigo, info]) => {
    expresion.push(codigo, info.color);
  });
  expresion.push('#888888'); // color por defecto, por si aparece algo no mapeado
  return expresion;
}

/**
 * Crea un marcador (punto + etiqueta con el nombre) por cada ciudad principal.
 * Los marcadores tienen pointer-events desactivados para no tapar los clicks
 * sobre los voivodatos que quedan debajo.
 */
function agregarMarcadoresDeCiudades() {
  CIUDADES_PRINCIPALES.forEach((ciudad) => {
    const el = document.createElement('div');
    el.className = 'marcador-ciudad' + (ciudad.capital ? ' marcador-ciudad--capital' : '');
    el.innerHTML = `<span class="marcador-punto"></span><span class="marcador-etiqueta">${ciudad.nombre}</span>`;

    new maplibregl.Marker({ element: el, anchor: 'bottom' })
      .setLngLat([ciudad.lon, ciudad.lat])
      .addTo(map);
  });
}

/**
 * Configura el hover y el click sobre los voivodatos, y la actualizacion
 * del panel lateral de informacion.
 */
function configurarInteracciones() {
  // Cambia el cursor a "pointer" cuando el mouse pasa por un voivodato.
  map.on('mousemove', 'voivodatos-relleno', (e) => {
    if (!e.features.length) return;
    map.getCanvas().style.cursor = 'pointer';

    const feature = e.features[0];
    if (idVoivodatoHover !== null && idVoivodatoHover !== feature.id) {
      map.setFeatureState({ source: 'voivodatos', id: idVoivodatoHover }, { hover: false });
    }
    idVoivodatoHover = feature.id;
    map.setFeatureState({ source: 'voivodatos', id: idVoivodatoHover }, { hover: true });
  });

  map.on('mouseleave', 'voivodatos-relleno', () => {
    map.getCanvas().style.cursor = '';
    if (idVoivodatoHover !== null) {
      map.setFeatureState({ source: 'voivodatos', id: idVoivodatoHover }, { hover: false });
    }
    idVoivodatoHover = null;
  });

  // Al clickear un voivodato: lo marca como "seleccionado" y muestra sus
  // datos en el panel lateral.
  map.on('click', 'voivodatos-relleno', (e) => {
    if (!e.features.length) return;
    const feature = e.features[0];

    if (idVoivodatoSeleccionado !== null) {
      map.setFeatureState({ source: 'voivodatos', id: idVoivodatoSeleccionado }, { seleccionada: false });
    }
    idVoivodatoSeleccionado = feature.id;
    map.setFeatureState({ source: 'voivodatos', id: idVoivodatoSeleccionado }, { seleccionada: true });

    mostrarInfoVoivodato(feature.properties.kod);
  });

  // Boton para restablecer la vista de camara (zoom/inclinacion/rotacion).
  document.getElementById('btn-reset-vista').addEventListener('click', () => {
    map.easeTo({ ...CONFIG_CAMARA, duration: 900 });
  });

  // Boton para cerrar el panel de informacion (vuelve al estado inicial).
  document.getElementById('panel-cerrar').addEventListener('click', cerrarPanel);
}

/**
 * Actualiza el contenido del panel lateral con los datos del voivodato
 * indicado (buscando por su codigo "kod" en WOJEWODZTWO_INFO).
 */
function mostrarInfoVoivodato(kod) {
  const info = WOJEWODZTWO_INFO[kod];
  const panel = document.getElementById('panel');
  const contenido = document.getElementById('panel-contenido');
  if (!info) return;

  contenido.innerHTML = `
    <h2>${info.nombre}</h2>
    <dl class="panel-datos">
      <div class="panel-dato">
        <dt>Capital regional</dt>
        <dd>${info.capital}</dd>
      </div>
      <div class="panel-dato">
        <dt>Poblacion aproximada</dt>
        <dd>${info.poblacion.toLocaleString('es-AR')} hab.</dd>
      </div>
    </dl>
    <p class="panel-nota">* Poblacion aproximada, con fines educativos.</p>
  `;
  panel.classList.add('panel--con-datos');
}

/** Vuelve el panel a su estado inicial (sin voivodato seleccionado). */
function cerrarPanel() {
  if (idVoivodatoSeleccionado !== null) {
    map.setFeatureState({ source: 'voivodatos', id: idVoivodatoSeleccionado }, { seleccionada: false });
    idVoivodatoSeleccionado = null;
  }
  document.getElementById('panel').classList.remove('panel--con-datos');
  document.getElementById('panel-contenido').innerHTML =
    '<p class="panel-placeholder">👆 Hacé click en un voivodato del mapa para ver su información.</p>';
}

/** Oculta la pantalla de carga inicial una vez que el mapa esta listo. */
function ocultarPantallaCarga() {
  const loader = document.getElementById('loader');
  if (loader) loader.classList.add('loader--oculto');
}
